const QB = {"de":[{"q":"Ngày Công dân số Việt Nam là ngày nào trong năm?","a":"Ngày 15/10","w":["Ngày 10/10","Ngày 1/10","Ngày 2/9"],"h":"Chỉ sau Ngày Chuyển đổi số quốc gia đúng 5 ngày.","e":"Khoản 1 Điều 9 Nghị quyết số 66.22/2026/NQ-CP ngày 09/7/2026 của Chính phủ lấy ngày 15 tháng 10 hằng năm là Ngày Công dân số Việt Nam. Ngày 10/10 là Ngày Chuyển đổi số quốc gia, 1/10 là Ngày Quốc tế Người cao tuổi, 2/9 là Ngày Quốc khánh."},{"q":"Dùng chữ ký số công cộng trên ứng dụng VNeID để làm thủ tục hành chính, dịch vụ công trực tuyến, người dân có phải trả phí không?","a":"Không, được cung cấp miễn phí","w":["Có, trả phí theo từng lần ký","Có, phải đăng ký gói thuê bao theo năm","Chỉ miễn phí cho cán bộ, công chức"],"h":"Đây là một trong những ưu đãi lớn nhất dành cho công dân số.","e":"Điểm b khoản 1 Điều 7 Nghị quyết số 66.22/2026/NQ-CP quy định ứng dụng định danh quốc gia cung cấp miễn phí dịch vụ chứng thực chữ ký số công cộng cho cá nhân để thực hiện dịch vụ công trực tuyến, thủ tục hành chính."},{"q":"Muốn được miễn phí, lệ phí theo Nghị quyết số 66.22/2026/NQ-CP, người dân nộp hồ sơ bằng cách nào?","a":"Nộp qua dịch vụ công trực tuyến","w":["Nộp qua đường bưu điện","Nhờ người quen nộp hộ tại bộ phận một cửa","Gửi hồ sơ qua Zalo cho cán bộ"],"h":"Ưu đãi dành cho người làm thủ tục trên môi trường số.","e":"Theo Phụ lục II Nghị quyết số 66.22/2026/NQ-CP, điều kiện được miễn phí, lệ phí gồm: hoàn thành tích hợp 05 loại thông tin, giấy tờ cơ bản (và giấy tờ của thủ tục cần làm) trên VNeID và thực hiện thủ tục qua dịch vụ công trực tuyến. Gửi hồ sơ qua Zalo cho cán bộ không phải cách nộp hồ sơ hợp lệ."},{"q":"Giấy tờ nào sau đây thuộc 05 loại giấy tờ, thông tin cơ bản cần tích hợp trên VNeID?","a":"Giấy khai sinh","w":["Hộ chiếu","Giấy phép lái xe","Giấy chứng nhận quyền sử dụng đất"],"h":"Giấy tờ đầu tiên mỗi người có khi chào đời.","e":"Theo Phụ lục I Nghị quyết số 66.22/2026/NQ-CP, 05 loại cơ bản gồm: Giấy khai sinh; thẻ ngân hàng, tài khoản thanh toán, ví điện tử, tài khoản tiền di động; tài khoản an sinh xã hội; số thuê bao di động; sổ sức khỏe điện tử. Hộ chiếu, giấy phép lái xe, giấy chứng nhận quyền sử dụng đất được tích hợp thêm khi làm thủ tục tương ứng."},{"q":"Muốn hưởng ưu đãi công dân số, mỗi người cần tích hợp bao nhiêu loại giấy tờ, thông tin cơ bản trên VNeID?","a":"05 loại","w":["03 loại","10 loại","12 loại"],"h":"Bằng số ngón tay trên một bàn tay.","e":"Khoản 1 Điều 5 Nghị quyết số 66.22/2026/NQ-CP yêu cầu công dân hoàn thành tích hợp 05 loại thông tin, giấy tờ cơ bản theo Phụ lục I. Phụ lục I có tổng cộng 12 loại, trong đó 05 loại cơ bản; 07 loại còn lại tích hợp theo thủ tục cần làm."},{"q":"Thông tin nào sau đây cũng nằm trong 05 loại cơ bản cần tích hợp trên VNeID?","a":"Số thuê bao di động","w":["Chứng nhận đăng ký xe","Thông tin lý lịch tư pháp","Văn bằng, chứng chỉ"],"h":"Thứ bạn dùng để nghe gọi mỗi ngày.","e":"Số thuê bao di động là một trong 05 loại cơ bản tại Phụ lục I Nghị quyết số 66.22/2026/NQ-CP. Chứng nhận đăng ký xe, lý lịch tư pháp, văn bằng, chứng chỉ thuộc nhóm tích hợp thêm theo thủ tục cần làm."},{"q":"Công dân đủ điều kiện công dân số cấp đổi thẻ Căn cước qua dịch vụ công trực tuyến thì nộp lệ phí bao nhiêu?","a":"0 đồng","w":["15.000 đồng","30.000 đồng","50.000 đồng"],"h":"Con số nhỏ nhất có thể.","e":"Phụ lục II Nghị quyết số 66.22/2026/NQ-CP quy định mức thu ưu đãi đối với lệ phí cấp đổi, cấp lại thẻ Căn cước là 0 đồng khi công dân hoàn thành tích hợp 05 loại giấy tờ cơ bản trên VNeID và làm thủ tục qua dịch vụ công trực tuyến."},{"q":"Tích hợp tài khoản an sinh xã hội trên VNeID giúp người dân điều gì?","a":"Nhận các khoản chi trả an sinh xã hội thuận tiện, đúng người","w":["Được vay tiền ngân hàng không lãi suất","Được miễn đóng bảo hiểm y tế","Được cấp thêm thẻ ngân hàng mới"],"h":"“An sinh” là các khoản Nhà nước hỗ trợ người dân.","e":"Tài khoản an sinh xã hội là một trong 05 loại thông tin cơ bản tại Phụ lục I Nghị quyết số 66.22/2026/NQ-CP; điểm d khoản 1 Điều 7 quy định VNeID liên kết tài khoản để hỗ trợ thanh toán dịch vụ công, chi trả an sinh xã hội. Các đáp án còn lại không có trong quy định."},{"q":"Sổ sức khỏe điện tử tích hợp trên VNeID lưu thông tin gì?","a":"Thông tin khám, chữa bệnh của người dân","w":["Lịch sử mua sắm trên mạng","Danh bạ điện thoại","Số dư tài khoản ngân hàng"],"h":"Liên quan đến bệnh viện, trạm y tế.","e":"Sổ sức khỏe điện tử thuộc lĩnh vực khám bệnh, chữa bệnh do Bộ Y tế quản lý, là một trong 05 loại cơ bản tại Phụ lục I Nghị quyết số 66.22/2026/NQ-CP. Bộ Y tế phối hợp với Bộ Công an hướng dẫn cơ sở y tế kết nối, chia sẻ dữ liệu lên VNeID (khoản 7 Điều 9)."},{"q":"Ứng dụng định danh quốc gia VNeID do bộ nào quản lý, phát triển?","a":"Bộ Công an","w":["Bộ Khoa học và Công nghệ","Bộ Tư pháp","Bộ Tài chính"],"h":"Cũng là nơi cấp thẻ Căn cước cho bạn.","e":"Khoản 2 Điều 7 Nghị quyết số 66.22/2026/NQ-CP giao Cục Cảnh sát quản lý hành chính về trật tự xã hội – Bộ Công an là cơ quan chủ quản, quản lý, phát triển ứng dụng định danh quốc gia."},{"q":"Tổ công nghệ số cộng đồng hỗ trợ người dân theo phương châm nào?","a":"Đi từng ngõ, gõ từng nhà, hướng dẫn từng người","w":["Người dân tự tìm hiểu, tự làm","Chỉ hướng dẫn qua điện thoại","Chỉ hỗ trợ tại trụ sở Ủy ban nhân dân phường"],"h":"Tổ đến tận nhà dân.","e":"Công văn số 11520/SKHCN-KTSXHS ngày 20/10/2026 của Sở Khoa học và Công nghệ đề nghị huy động Tổ công nghệ số cộng đồng thực hiện phương châm “đi từng ngõ, gõ từng nhà, hướng dẫn từng người”, trực tiếp hỗ trợ công dân tích hợp giấy tờ và tiếp cận các tiện ích công dân số."},{"q":"Ông bà lớn tuổi chưa rành điện thoại muốn tích hợp giấy tờ lên VNeID thì nên làm gì?","a":"Nhờ Tổ công nghệ số cộng đồng khu phố hoặc đến điểm hỗ trợ của phường","w":["Đưa điện thoại và mật khẩu cho người lạ làm giúp","Bỏ qua vì người cao tuổi không được hưởng ưu đãi","Gọi vào số điện thoại lạ tự giới thiệu là hỗ trợ VNeID"],"h":"Hãy nhờ người có trách nhiệm, đừng nhờ người lạ.","e":"Phường bố trí điểm hỗ trợ và Tổ công nghệ số cộng đồng để hướng dẫn trực tiếp, ưu tiên người cao tuổi. Người cao tuổi còn được áp dụng mức ưu đãi cao nhất theo khoản 2 Điều 5 Nghị quyết số 66.22/2026/NQ-CP. Không đưa mật khẩu cho người lạ hay gọi vào số lạ vì dễ bị lừa đảo."},{"q":"Ngày Chuyển đổi số quốc gia là ngày nào trong năm?","a":"Ngày 10/10","w":["Ngày 1/10","Ngày 20/11","Ngày 2/9"],"h":"Ngày và tháng giống hệt nhau, gợi nhớ hai chữ số 1 và 0 của máy tính.","e":"Quyết định số 505/QĐ-TTg ngày 22/4/2022 của Thủ tướng Chính phủ lấy ngày 10/10 hằng năm là Ngày Chuyển đổi số quốc gia; con số 10 gợi nhớ hai chữ số 1 và 0 của máy tính. Ngày 1/10 là Ngày Quốc tế Người cao tuổi, 20/11 là Ngày Nhà giáo Việt Nam, 2/9 là Ngày Quốc khánh."},{"q":"VNeID là gì?","a":"Ứng dụng định danh và xác thực điện tử do Bộ Công an phát triển","w":["Ứng dụng mạng xã hội để kết bạn, nhắn tin","Ví điện tử của một ngân hàng","Ứng dụng gọi xe công nghệ"],"h":"“ID” là viết tắt tiếng Anh của từ “danh tính”.","e":"VNeID là ứng dụng định danh điện tử của Bộ Công an, giúp người dân dùng giấy tờ điện tử thay giấy tờ giấy, đăng nhập dịch vụ công, tra cứu thông tin cư trú. VNeID không phải mạng xã hội, ví điện tử hay ứng dụng gọi xe."},{"q":"Khi thanh toán bằng cách quét mã QR, cần làm gì trước khi bấm xác nhận chuyển tiền?","a":"Kiểm tra tên người nhận và số tiền hiển thị trên ứng dụng","w":["Chụp màn hình gửi cho người thân","Tắt mạng điện thoại","Đọc to số tài khoản cho người bán nghe"],"h":"Hãy nhìn kỹ màn hình trước khi bấm nút cuối cùng.","e":"Kẻ gian có thể dán đè mã QR giả lên mã thật. Kiểm tra tên người nhận và số tiền giúp tránh chuyển nhầm hoặc chuyển cho kẻ gian. Các việc còn lại không giúp kiểm tra giao dịch."},{"q":"Bạn nhận tin nhắn: “Chúc mừng bạn trúng xe máy, bấm vào đường link để nhận thưởng”. Bạn nên làm gì?","a":"Không bấm link, xóa tin nhắn và cảnh báo người thân","w":["Bấm vào link ngay để nhận thưởng","Gửi ảnh thẻ căn cước để làm thủ tục nhận thưởng","Chuyển khoản “phí nhận thưởng” theo yêu cầu"],"h":"Quà to từ người lạ thường là cái bẫy.","e":"Đây là chiêu lừa đảo phổ biến: đường link lạ có thể cài mã độc, đánh cắp tài khoản; yêu cầu gửi giấy tờ hoặc nộp phí để nhận thưởng đều là dấu hiệu lừa đảo."},{"q":"Một người tự xưng là nhân viên ngân hàng gọi điện xin mã OTP vừa gửi về máy bạn. Bạn nên làm gì?","a":"Không cung cấp, cúp máy và gọi lại tổng đài chính thức của ngân hàng","w":["Đọc mã vì họ biết đúng họ tên của mình","Đọc mã nếu họ nói chuyện lịch sự","Gửi mã qua Zalo cho họ"],"h":"Mã OTP là chìa khóa riêng, ngân hàng không bao giờ xin.","e":"Ngân hàng không bao giờ yêu cầu khách hàng cung cấp mã OTP. Ai có mã OTP có thể thực hiện giao dịch trên tài khoản của bạn. Kẻ gian thường biết trước họ tên, số điện thoại, nên đừng vì thế mà tin."},{"q":"Dịch vụ công trực tuyến mang lại lợi ích gì cho người dân?","a":"Nộp hồ sơ thủ tục hành chính qua mạng, giảm đi lại, tiết kiệm thời gian","w":["Mua hàng giảm giá trên mạng","Xem phim miễn phí","Nhận tiền thưởng mỗi lần đăng nhập"],"h":"Chữ “công” trong tên gọi liên quan đến cơ quan nhà nước.","e":"Dịch vụ công trực tuyến là dịch vụ hành chính công được cơ quan nhà nước cung cấp qua mạng, giúp người dân nộp hồ sơ, theo dõi tiến độ và nhận kết quả mà không phải đến nhiều lần. Các đáp án còn lại không phải dịch vụ công."},{"q":"Ứng dụng nào cho phép bạn tra cứu thông tin cư trú của bản thân?","a":"VNeID","w":["YouTube","TikTok","Google Maps"],"h":"Ứng dụng này do Bộ Công an phát triển.","e":"VNeID cho phép xem thông tin cư trú, thông tin thẻ căn cước và nhiều giấy tờ đã tích hợp. Các ứng dụng còn lại dùng để xem video, mạng xã hội hoặc bản đồ."},{"q":"Trước khi chia sẻ một tin “nóng” trên mạng xã hội, bạn nên làm gì?","a":"Kiểm tra lại từ nguồn chính thống như báo chí, trang của cơ quan nhà nước","w":["Chia sẻ ngay nếu có nhiều lượt thích","Chia sẻ nếu tiêu đề gây sốc","Cứ chia sẻ trước, sai thì xóa sau"],"h":"Nhiều người thích chưa chắc đã đúng.","e":"Tin giả lan rất nhanh, gây hoang mang; người chia sẻ thông tin sai sự thật có thể bị xử lý theo quy định. Lượt thích hay tiêu đề giật gân không chứng minh tin là thật."}],"tb":[{"q":"Muốn hưởng chính sách công dân số theo Nghị quyết số 66.22/2026/NQ-CP, người dân phải có tài khoản định danh điện tử mức độ nào?","a":"Mức độ 2","w":["Mức độ 1","Mức độ 1 hoặc mức độ 2 đều được","Không cần tài khoản định danh điện tử"],"h":"Mức có độ tin cậy cao hơn.","e":"Điều 3 Nghị quyết số 66.22/2026/NQ-CP quy định công dân được hưởng chính sách là công dân Việt Nam có tài khoản định danh điện tử mức độ 2, đáp ứng các điều kiện tại khoản 1 Điều 5."},{"q":"Nhóm nào dưới đây là ĐÚNG VÀ ĐỦ 05 loại giấy tờ, thông tin cơ bản cần tích hợp trên VNeID?","a":"Giấy khai sinh; tài khoản thanh toán; tài khoản an sinh xã hội; số thuê bao di động; sổ sức khỏe điện tử","w":["Giấy khai sinh; hộ chiếu; giấy phép lái xe; số thuê bao di động; sổ sức khỏe điện tử","Thẻ Căn cước; tài khoản thanh toán; mã số thuế; chứng nhận đăng ký xe; giấy đăng ký kết hôn","Giấy khai sinh; tài khoản thanh toán; lý lịch tư pháp; văn bằng, chứng chỉ; số thuê bao di động"],"h":"Không có giấy tờ nào liên quan đến xe cộ hay đi nước ngoài.","e":"Phụ lục I Nghị quyết số 66.22/2026/NQ-CP ghi chú “Cơ bản” cho 05 loại: Giấy khai sinh; thẻ ngân hàng, tài khoản thanh toán, ví điện tử, tài khoản tiền di động; tài khoản an sinh xã hội; số thuê bao di động; sổ sức khỏe điện tử. Các giấy tờ khác tích hợp theo thủ tục cần làm."},{"q":"Muốn được miễn lệ phí cấp đổi giấy phép lái xe, ngoài 05 loại cơ bản, người dân cần tích hợp thêm giấy tờ nào trên VNeID?","a":"Giấy phép lái xe","w":["Hộ chiếu","Giấy chứng nhận quyền sử dụng đất","Văn bằng, chứng chỉ"],"h":"Đổi giấy tờ nào thì tích hợp giấy tờ đó.","e":"Theo Phụ lục II Nghị quyết số 66.22/2026/NQ-CP, lệ phí cấp đổi, cấp lại giấy phép lái xe (thông thường 115.000 đồng) được áp dụng mức 0 đồng khi công dân tích hợp thành công giấy phép lái xe và 05 loại giấy tờ cơ bản trên VNeID, đồng thời làm thủ tục qua dịch vụ công trực tuyến."},{"q":"Mức độ được hưởng chính sách ưu đãi của mỗi công dân được hiển thị ở đâu?","a":"Trên ứng dụng VNeID, gắn với tài khoản định danh điện tử của người đó","w":["Trên bảng tin của khu phố","Trên mặt thẻ Căn cước","Chỉ cán bộ phường mới xem được"],"h":"Bạn tự mở điện thoại là thấy.","e":"Điểm a khoản 3 Điều 5 Nghị quyết số 66.22/2026/NQ-CP quy định mức độ được hưởng chính sách được hiển thị trên ứng dụng định danh quốc gia, gắn với tài khoản định danh điện tử của cá nhân đó."},{"q":"Nghị quyết số 66.22/2026/NQ-CP về phát triển công dân số có hiệu lực trong thời gian nào?","a":"Từ ngày 15/8/2026 đến ngày 28/02/2027","w":["Từ ngày 09/7/2026, không có thời hạn","Từ ngày 01/01/2027 đến ngày 31/12/2030","Từ ngày 15/10/2026 đến ngày 15/10/2027"],"h":"Ưu đãi có thời hạn, đừng chần chừ!","e":"Khoản 1 Điều 10 Nghị quyết số 66.22/2026/NQ-CP quy định Nghị quyết có hiệu lực thi hành từ ngày 15/8/2026 đến ngày 28/02/2027. Ngày 09/7/2026 là ngày ban hành; ngày 15/10 là Ngày Công dân số Việt Nam."},{"q":"Người cao tuổi, người khuyết tật, đồng bào dân tộc thiểu số nếu cùng lúc được hưởng nhiều chính sách ưu đãi thì được áp dụng mức nào?","a":"Mức ưu đãi cao nhất","w":["Mức ưu đãi thấp nhất","Cộng dồn tất cả các mức ưu đãi","Chỉ được hưởng chính sách công dân số"],"h":"Nhà nước ưu tiên các nhóm yếu thế.","e":"Khoản 2 Điều 5 Nghị quyết số 66.22/2026/NQ-CP quy định công dân là người cao tuổi, người khuyết tật, đồng bào dân tộc thiểu số hoặc đối tượng khác được hưởng chính sách khuyến khích khác thì được áp dụng mức ưu đãi cao nhất."},{"q":"Nếu không muốn làm thủ tục qua mạng, người dân có còn được nộp hồ sơ trực tiếp không?","a":"Có, người dân vẫn được tự lựa chọn cách thực hiện thủ tục","w":["Không, từ nay bắt buộc làm qua mạng","Được, nhưng phải nộp thêm phí","Chỉ người trên 70 tuổi mới được nộp trực tiếp"],"h":"Ưu đãi là để khuyến khích, không phải bắt buộc.","e":"Khoản 4 Điều 5 Nghị quyết số 66.22/2026/NQ-CP quy định việc áp dụng chính sách khuyến khích không làm hạn chế quyền của công dân trong việc lựa chọn phương thức tiếp cận, thực hiện thủ tục hành chính, dịch vụ công. Khoản 1 Điều 2 cũng nêu nguyên tắc không làm phát sinh nghĩa vụ, hạn chế quyền ngoài phạm vi luật định."},{"q":"Công dân đủ điều kiện công dân số đăng ký thường trú, tạm trú qua dịch vụ công trực tuyến thì nộp lệ phí bao nhiêu?","a":"0 đồng","w":["10.000 đồng/lần","20.000 đồng/lần","Một nửa mức thu thông thường"],"h":"Giống như khi cấp đổi thẻ Căn cước.","e":"Phụ lục II Nghị quyết số 66.22/2026/NQ-CP quy định mức thu ưu đãi 0 đồng đối với lệ phí đăng ký thường trú, đăng ký và gia hạn tạm trú, tách hộ khi công dân hoàn thành tích hợp 05 loại giấy tờ cơ bản trên VNeID và làm thủ tục qua dịch vụ công trực tuyến."},{"q":"Muốn được miễn lệ phí đăng ký lại kết hôn, cấp Giấy xác nhận tình trạng hôn nhân, ngoài 05 loại cơ bản cần tích hợp thêm giấy tờ nào?","a":"Giấy đăng ký kết hôn","w":["Giấy phép lái xe","Hộ chiếu","Thông tin mã số thuế cá nhân"],"h":"Giấy tờ chứng minh hai người đã là vợ chồng.","e":"Theo Phụ lục II Nghị quyết số 66.22/2026/NQ-CP, để được miễn lệ phí đăng ký lại kết hôn và cấp Giấy xác nhận tình trạng hôn nhân, công dân phải tích hợp thành công trên VNeID thông tin Giấy đăng ký kết hôn và 05 loại giấy tờ cơ bản, đồng thời nộp hồ sơ qua dịch vụ công trực tuyến."},{"q":"Văn bản nào lấy ngày 15/10 hằng năm là Ngày Công dân số Việt Nam?","a":"Nghị quyết số 66.22/2026/NQ-CP của Chính phủ","w":["Quyết định số 505/QĐ-TTg của Thủ tướng Chính phủ","Nghị quyết số 57-NQ/TW của Bộ Chính trị","Luật Giao dịch điện tử 2023"],"h":"Văn bản về phát triển công dân số.","e":"Khoản 1 Điều 9 Nghị quyết số 66.22/2026/NQ-CP ngày 09/7/2026 của Chính phủ lấy ngày 15/10 hằng năm là Ngày Công dân số Việt Nam. Quyết định số 505/QĐ-TTg quy định ngày 10/10 là Ngày Chuyển đổi số quốc gia."},{"q":"Theo Nghị quyết số 66.22/2026/NQ-CP, ứng dụng VNeID là kênh giao tiếp chính thức giữa những ai?","a":"Người dân với Nhà nước, người dân với doanh nghiệp và người dân với người dân","w":["Chỉ giữa các cơ quan nhà nước với nhau","Chỉ giữa người dân với ngân hàng","Chỉ giữa cán bộ công an với nhau"],"h":"Kênh này dành cho cả người dân.","e":"Điểm đ khoản 1 Điều 7 Nghị quyết số 66.22/2026/NQ-CP quy định ứng dụng định danh quốc gia cung cấp kênh giao tiếp chính thức, bảo đảm an toàn, bảo mật, hiệu quả giữa người dân với Nhà nước, người dân với doanh nghiệp và người dân với người dân."},{"q":"Khi tích hợp thông tin cá nhân vào tài khoản định danh điện tử, công dân có trách nhiệm gì?","a":"Chủ động cung cấp, cập nhật thông tin chính xác","w":["Chỉ khai báo một lần, không cần cập nhật","Có thể khai thông tin của người khác cho nhanh","Không có trách nhiệm gì"],"h":"Thông tin đúng thì quyền lợi mới đúng.","e":"Khoản 2 Điều 4 Nghị quyết số 66.22/2026/NQ-CP quy định công dân có trách nhiệm chủ động phối hợp cung cấp, cập nhật và tích hợp thông tin cá nhân chính xác vào tài khoản định danh điện tử và các cơ sở dữ liệu."},{"q":"“Dịch vụ công trực tuyến toàn trình” nghĩa là gì?","a":"Mọi bước từ nộp hồ sơ, xử lý đến nhận kết quả đều thực hiện trên môi trường mạng","w":["Nộp hồ sơ trên mạng, khi nhận kết quả mang bản giấy đến đối chiếu","Điền tờ khai trên mạng, in ra rồi nộp tại Trung tâm Phục vụ hành chính công","Nộp hồ sơ được tại bất kỳ xã, phường nào trên cả nước"],"h":"“Toàn trình” là không có bước nào phải đến trực tiếp.","e":"Toàn trình là thực hiện trọn vẹn trên mạng. Hai cách “nộp mạng rồi mang giấy đến” hay “điền mạng rồi nộp giấy” chỉ là dịch vụ công trực tuyến một phần. Nộp ở bất kỳ xã, phường nào là “không phụ thuộc địa giới hành chính”, một khái niệm khác."},{"q":"Theo quy định hiện hành, tài khoản định danh điện tử của công dân Việt Nam được chia thành mấy mức độ?","a":"2 mức độ (mức độ 1 và mức độ 2)","w":["3 mức độ (mức độ 1, 2 và 3)","4 mức độ (từ mức độ 1 đến mức độ 4)","1 mức độ chung cho mọi công dân"],"h":"Chỉ có “mức 1” và một mức cao hơn nó.","e":"Theo Nghị định 69/2024/NĐ-CP (đã được sửa đổi, bổ sung năm 2026), tài khoản định danh điện tử của công dân gồm mức độ 1 và mức độ 2; mức độ 2 có thêm thông tin vân tay nên độ tin cậy cao hơn. Cách chia 4 mức là cách phân loại dịch vụ công trực tuyến trước đây, không phải tài khoản định danh."},{"q":"Theo Luật Căn cước 2023 (hiệu lực từ 01/7/2024), thẻ Căn cước công dân được đổi tên thành gì?","a":"Thẻ căn cước","w":["Thẻ căn cước điện tử","Thẻ định danh công dân","Thẻ căn cước công dân gắn chip"],"h":"Tên mới chỉ còn hai chữ.","e":"Luật Căn cước 2023 đổi tên thành “thẻ căn cước”; thẻ Căn cước công dân cấp trước đó vẫn dùng đến hết hạn in trên thẻ. “Căn cước điện tử” là loại khác: mỗi công dân được cấp 01 căn cước điện tử, không phải tên của thẻ. “Thẻ căn cước công dân gắn chip” là tên gọi cũ; “thẻ định danh công dân” không có trong luật."},{"q":"Có người gọi điện xưng là công an, nói bạn liên quan vụ án và yêu cầu chuyển tiền vào “tài khoản tạm giữ” để điều tra. Trường hợp nào thì làm theo?","a":"Không trường hợp nào, đây là thủ đoạn lừa đảo","w":["Khi người gọi đọc chính xác họ tên, số căn cước của bạn","Khi họ gửi kèm ảnh giấy triệu tập có đóng dấu đỏ qua Zalo","Khi họ cam kết hoàn trả lại tiền ngay trong ngày"],"h":"Công an làm việc bằng giấy mời trực tiếp, không yêu cầu chuyển tiền qua điện thoại.","e":"Cơ quan công an không làm việc qua điện thoại để yêu cầu chuyển tiền; không có “tài khoản tạm giữ” nào như vậy. Kẻ gian thường biết trước thông tin cá nhân, làm giả giấy triệu tập và hứa hoàn tiền để tạo lòng tin. Khi nghi ngờ, hãy đến trực tiếp Công an phường."},{"q":"Nguồn nào sau đây an toàn để cài ứng dụng cho điện thoại?","a":"Kho ứng dụng chính thức như CH Play (Google Play) hoặc App Store","w":["Đường link “cán bộ” gửi qua Zalo để cài bản dịch vụ công mới","File cài đặt tải từ trang web có giao diện giống trang cơ quan nhà nước","Đường link trong tin nhắn hiện đúng tên ngân hàng của bạn"],"h":"Hãy cài từ “cửa hàng” chính hãng có sẵn trên máy.","e":"Kẻ gian thường gửi link hoặc file cài ứng dụng giả mạo (kể cả giả ứng dụng dịch vụ công, giả trang nhà nước, giả tin nhắn ngân hàng) để chiếm quyền điều khiển điện thoại và rút tiền. Kho ứng dụng chính thức có kiểm duyệt nên an toàn hơn."},{"q":"Mã VietQR giúp người dân làm gì?","a":"Quét một mã để chuyển tiền đến tài khoản ở nhiều ngân hàng khác nhau","w":["Chỉ chuyển được tiền giữa các tài khoản trong cùng một ngân hàng","Chỉ dùng cho ví điện tử, không dùng cho tài khoản ngân hàng","Chỉ dùng để thanh toán tại siêu thị có máy quẹt thẻ"],"h":"“Viet” là Việt Nam, “QR” là loại mã vuông bạn hay quét.","e":"VietQR là nhận diện chung cho dịch vụ thanh toán, chuyển khoản bằng mã QR qua mạng lưới NAPAS và các ngân hàng thành viên, ra mắt tháng 6/2021, giúp quét một mã để chuyển khoản liên ngân hàng nhanh chóng."},{"q":"Phong trào “Bình dân học vụ số” nhằm mục đích chính nào?","a":"Phổ cập kiến thức, kỹ năng số cơ bản cho mọi người dân","w":["Xóa mù chữ cho người lớn tuổi chưa biết đọc, viết","Đào tạo chuyên sâu về lập trình, AI cho học sinh, sinh viên","Hỗ trợ mỗi hộ gia đình một thiết bị thông minh"],"h":"Tên gọi kế thừa phong trào “Bình dân học vụ” năm 1945, thêm chữ “số”.","e":"Phong trào được triển khai theo Kế hoạch số 01-KH/BCĐTW ngày 21/3/2025 của Ban Chỉ đạo Trung ương về phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số, có nền tảng học tập binhdanhocvuso.gov.vn. Xóa mù chữ là mục tiêu của phong trào Bình dân học vụ năm 1945; đào tạo chuyên sâu hay phát thiết bị không phải mục tiêu chính."},{"q":"Đang gọi video, người thân bất ngờ hỏi vay tiền gấp. Cách xác minh nào an toàn nhất?","a":"Cúp máy, gọi lại vào số điện thoại quen thuộc của người đó hoặc hỏi trực tiếp người nhà","w":["Đề nghị họ bật camera lâu hơn để nhìn kỹ khuôn mặt","Kiểm tra tên hiển thị trên Zalo, Facebook đúng là của người thân","Chuyển trước một ít tiền để thử xem họ có thật không"],"h":"Đừng chỉ tin vào màn hình và tài khoản đang gọi cho bạn.","e":"Kẻ gian có thể chiếm tài khoản mạng xã hội của người thân và dùng AI giả khuôn mặt, giọng nói, nên nhìn lâu hay xem tên tài khoản đều không đủ. Chuyển thử tiền là đã mất tiền. Gọi lại qua số quen hoặc hỏi người nhà là cách chắc chắn nhất."}],"kho":[{"q":"Nghị quyết số 66.22/2026/NQ-CP về phát triển công dân số do cơ quan nào ban hành, vào ngày nào?","a":"Chính phủ, ngày 09/7/2026","w":["Quốc hội, ngày 09/7/2026","Thủ tướng Chính phủ, ngày 15/10/2026","Bộ Công an, ngày 15/8/2026"],"h":"Ký hiệu “NQ-CP” đã gợi ý cơ quan ban hành.","e":"Nghị quyết số 66.22/2026/NQ-CP do Chính phủ ban hành ngày 09/7/2026, theo đề nghị của Bộ trưởng Bộ Công an. Ngày 15/8/2026 là ngày Nghị quyết có hiệu lực; ngày 15/10 là Ngày Công dân số Việt Nam."},{"q":"Cơ quan nào là cơ quan chủ quản, vận hành hệ thống định danh và xác thực điện tử, quản lý, phát triển ứng dụng VNeID?","a":"Cục Cảnh sát quản lý hành chính về trật tự xã hội – Bộ Công an","w":["Cục Chuyển đổi số quốc gia – Bộ Khoa học và Công nghệ","Văn phòng Chính phủ","Ngân hàng Nhà nước Việt Nam"],"h":"Cơ quan này còn được gọi tắt là C06.","e":"Khoản 2 Điều 7 Nghị quyết số 66.22/2026/NQ-CP quy định cơ quan chủ quản, vận hành hệ thống định danh và xác thực điện tử và quản lý, phát triển ứng dụng định danh quốc gia là Cục Cảnh sát quản lý hành chính về trật tự xã hội – Bộ Công an."},{"q":"Công dân số đáp ứng điều kiện thì được ưu đãi thế nào đối với lệ phí trước bạ xe mô tô?","a":"Miễn 100% lệ phí trước bạ","w":["Giảm 10% lệ phí trước bạ","Giảm 50% lệ phí trước bạ","Không được ưu đãi"],"h":"Xe máy là phương tiện phổ biến nhất nên được ưu đãi nhiều nhất.","e":"Theo Phụ lục III và Phụ lục IV Nghị quyết số 66.22/2026/NQ-CP, công dân có tài khoản định danh điện tử mức độ 2, khai và nộp lệ phí trước bạ bằng phương thức điện tử, đáp ứng điều kiện tích hợp thông tin trên VNeID thì được miễn 100% lệ phí trước bạ đối với xe mô tô (theo các trường hợp nêu tại Phụ lục III). Ô tô được giảm 50%, nhà, đất nhận chuyển nhượng được giảm 10%."},{"q":"Đối với nhà, đất nhận chuyển nhượng, công dân số đáp ứng điều kiện được giảm bao nhiêu lệ phí trước bạ?","a":"Giảm 10%","w":["Giảm 50%","Miễn 100%","Giảm 20%"],"h":"Con số nhỏ nhất trong các đáp án.","e":"Theo Phụ lục III Nghị quyết số 66.22/2026/NQ-CP, nhà, đất nhận chuyển nhượng khi đăng ký quyền sở hữu, quyền sử dụng được giảm 10% mức thu lệ phí trước bạ; chỉ áp dụng 01 lần trong năm và mức giảm tối đa không quá 05 lần mức lương cơ sở tại thời điểm kê khai."},{"q":"Phí cung cấp thông tin lý lịch tư pháp thông thường là 200.000 đồng/lần/người. Công dân số đáp ứng điều kiện, làm qua dịch vụ công trực tuyến thì phí là bao nhiêu?","a":"0 đồng","w":["100.000 đồng","50.000 đồng","200.000 đồng"],"h":"Giống ưu đãi khi cấp đổi thẻ Căn cước.","e":"Phụ lục II Nghị quyết số 66.22/2026/NQ-CP quy định mức thu ưu đãi 0 đồng đối với phí cấp Phiếu lý lịch tư pháp khi công dân tích hợp thành công thông tin lý lịch tư pháp và 05 loại giấy tờ cơ bản trên VNeID, đồng thời đăng ký qua dịch vụ công trực tuyến."},{"q":"Giấy tờ nào sau đây KHÔNG nằm trong danh mục giấy tờ, thông tin tích hợp trên VNeID theo Phụ lục I Nghị quyết số 66.22/2026/NQ-CP?","a":"Thẻ thư viện","w":["Thông tin mã số thuế cá nhân","Thông tin lý lịch tư pháp","Giấy đăng ký kết hôn"],"h":"Danh mục gồm giấy tờ do các bộ, ngành cấp.","e":"Phụ lục I gồm 12 loại: Giấy khai sinh; tài khoản thanh toán, ví điện tử; tài khoản an sinh xã hội; số thuê bao di động; sổ sức khỏe điện tử; giấy phép lái xe; chứng nhận đăng ký xe; văn bằng, chứng chỉ; giấy chứng nhận quyền sử dụng đất; lý lịch tư pháp; mã số thuế cá nhân; Giấy đăng ký kết hôn. Thẻ thư viện không có trong danh mục."},{"q":"Việc sử dụng tài khoản định danh điện tử, dịch vụ xác thực điện tử khi thực hiện thủ tục hành chính có giá trị pháp lý gì?","a":"Khẳng định chủ thể đã thực hiện, chấp thuận giao dịch, thủ tục đó","w":["Chỉ có giá trị tham khảo, phải ký tay bổ sung","Chỉ có giá trị khi được công chứng","Không có giá trị pháp lý"],"h":"Xác thực điện tử giống như bạn tự tay ký tên.","e":"Khoản 4 Điều 7 Nghị quyết số 66.22/2026/NQ-CP quy định việc sử dụng tài khoản định danh điện tử, dịch vụ xác thực điện tử trong thực hiện thủ tục hành chính, dịch vụ công trực tuyến có giá trị pháp lý khẳng định chủ thể đã thực hiện, chấp thuận giao dịch, thủ tục đó."},{"q":"Nhà nước khuyến khích tổ chức, doanh nghiệp cung cấp dịch vụ số làm gì cho công dân đáp ứng điều kiện công dân số?","a":"Triển khai chương trình ưu đãi, giảm giá vé, giảm giá dịch vụ, khuyến mại","w":["Tăng giá dịch vụ để bù chi phí kết nối","Bắt buộc mua gói cước mới","Thu thêm phí xác thực VNeID"],"h":"Là công dân số thì còn có thể được giảm giá.","e":"Khoản 3 Điều 6 Nghị quyết số 66.22/2026/NQ-CP: Nhà nước khuyến khích và tạo điều kiện để tổ chức, doanh nghiệp triển khai chương trình ưu đãi, giảm giá vé, giảm giá dịch vụ hoặc khuyến mại khác cho công dân đáp ứng điều kiện tại Điều 5. Đây là khuyến khích, không phải bắt buộc doanh nghiệp."},{"q":"Thông tin xác định đối tượng được hưởng chính sách khuyến khích công dân số phải được sử dụng như thế nào?","a":"Đúng mục đích, không dùng để phân biệt đối xử hay hạn chế quyền của công dân","w":["Công khai trên mạng xã hội để tuyên dương","Cung cấp cho doanh nghiệp để quảng cáo","Dùng để ưu tiên công dân số hơn người khác khi giải quyết thủ tục"],"h":"Ưu đãi không được biến thành phân biệt.","e":"Khoản 4 Điều 6 Nghị quyết số 66.22/2026/NQ-CP quy định cơ quan, tổ chức, doanh nghiệp, cá nhân phải sử dụng thông tin xác định đối tượng được hưởng chính sách khuyến khích đúng mục đích; không sử dụng để phân biệt đối xử hoặc hạn chế quyền, lợi ích hợp pháp của công dân dưới mọi hình thức."},{"q":"Bộ nào chủ trì thẩm định, cấp chứng thư chữ ký số cho cơ quan chủ quản để cung cấp dịch vụ chữ ký số công cộng trên ứng dụng VNeID?","a":"Bộ Khoa học và Công nghệ","w":["Bộ Tài chính","Bộ Tư pháp","Bộ Y tế"],"h":"Bộ quản lý lĩnh vực khoa học, công nghệ và chuyển đổi số.","e":"Theo Điều 9 Nghị quyết số 66.22/2026/NQ-CP, Bộ Khoa học và Công nghệ chủ trì, phối hợp với Bộ Công an, Ban Cơ yếu Chính phủ thẩm định, cấp chứng thư chữ ký số cho cơ quan chủ quản hệ thống để cung cấp dịch vụ chứng thực chữ ký số công cộng trên ứng dụng VNeID."},{"q":"Theo Nghị quyết số 66.22/2026/NQ-CP, Ủy ban nhân dân các tỉnh, thành phố chỉ đạo lực lượng nào trực tiếp hỗ trợ người dân tiếp cận các tiện ích công dân số?","a":"Tổ công nghệ số cộng đồng","w":["Đội dân phòng","Tổ bảo vệ an ninh, trật tự ở cơ sở","Ban quản trị nhà chung cư"],"h":"Lực lượng có mặt ở từng khu phố, chuyên về công nghệ số.","e":"Khoản 15 Điều 9 Nghị quyết số 66.22/2026/NQ-CP giao Ủy ban nhân dân các tỉnh, thành phố ban hành kế hoạch hành động, bố trí nguồn lực và chỉ đạo Tổ công nghệ số cộng đồng trực tiếp hỗ trợ người dân tiếp cận các tiện ích của công dân số."},{"q":"Bộ nào chủ trì hướng dẫn tích hợp thông tin văn bằng, chứng chỉ thuộc hệ thống giáo dục quốc dân trên ứng dụng VNeID?","a":"Bộ Giáo dục và Đào tạo","w":["Bộ Nội vụ","Bộ Khoa học và Công nghệ","Bộ Văn hóa, Thể thao và Du lịch"],"h":"Bộ quản lý trường học, bằng cấp.","e":"Khoản 9 Điều 9 Nghị quyết số 66.22/2026/NQ-CP giao Bộ Giáo dục và Đào tạo chủ trì, phối hợp với Bộ Công an hướng dẫn kết nối, chia sẻ dữ liệu để tích hợp thông tin văn bằng, chứng chỉ thuộc hệ thống giáo dục quốc dân trên ứng dụng định danh quốc gia."},{"q":"Nghị quyết số 57-NQ/TW ngày 22/12/2024 của Bộ Chính trị về vấn đề gì?","a":"Đột phá phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số quốc gia","w":["Phát triển kinh tế tư nhân","Hội nhập quốc tế trong tình hình mới","Đổi mới công tác xây dựng và thi hành pháp luật"],"h":"Nghị quyết này về khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số.","e":"Nghị quyết 57-NQ/TW xác định khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số là đột phá quan trọng hàng đầu để phát triển đất nước. Ba nội dung còn lại thuộc các nghị quyết khác của Bộ Chính trị."},{"q":"Theo Luật Giao dịch điện tử 2023, chữ ký số có giá trị pháp lý như thế nào?","a":"Tương đương chữ ký của người đó trên văn bản giấy","w":["Chỉ có giá trị khi in ra và đóng dấu xác nhận","Chỉ có giá trị trong giao dịch giữa các cơ quan nhà nước","Chỉ có giá trị như bản sao, khi cần phải kèm bản ký tay"],"h":"Chữ ký số giúp ký hồ sơ mà không cần in giấy.","e":"Điều 23 Luật Giao dịch điện tử 2023 (số 20/2023/QH15, hiệu lực từ 01/7/2024) quy định chữ ký số có giá trị pháp lý tương đương chữ ký của cá nhân đó trong văn bản giấy. Chữ ký số dùng được cho cả cá nhân, doanh nghiệp, không cần in ra hay kèm bản ký tay."},{"q":"Kẻ gian dùng AI tạo hình ảnh, giọng nói giống hệt người thân để gọi video lừa tiền. Hình thức giả mạo đó gọi là gì?","a":"Deepfake","w":["Phishing","Spoofing","Malware"],"h":"Tên gồm hai từ tiếng Anh có nghĩa là “sâu” và “giả”.","e":"Deepfake là dùng AI ghép, giả mạo khuôn mặt, giọng nói. Phishing là lừa đảo bằng trang web, email, tin nhắn giả để lấy thông tin; spoofing là giả mạo số điện thoại hoặc địa chỉ người gửi; malware là phần mềm độc hại."},{"q":"Làm thủ tục hành chính, thông tin về cư trú đã có trong cơ sở dữ liệu thì người dân có phải nộp giấy tờ chứng minh nơi cư trú không?","a":"Không, cơ quan giải quyết khai thác thông tin từ cơ sở dữ liệu","w":["Có, phải nộp giấy xác nhận thông tin về cư trú do công an cấp","Có, phải nộp bản sao thẻ căn cước có chứng thực","Chỉ không phải nộp nếu có tài khoản định danh mức độ 2"],"h":"Nguyên tắc là để dữ liệu “chạy” thay người dân.","e":"Từ khi bỏ sổ hộ khẩu, Nghị định 104/2022/NĐ-CP quy định các cách khai thác thông tin cư trú thay cho việc xuất trình sổ. Theo định hướng của Đề án 06, cơ quan nhà nước khai thác dữ liệu sẵn có thay vì yêu cầu người dân nộp giấy tờ chứng minh; giấy xác nhận cư trú chỉ dùng khi chưa khai thác được dữ liệu."},{"q":"Khi hỏi chatbot AI về thủ tục, quy định pháp luật, điều quan trọng nhất cần lưu ý là gì?","a":"AI có thể trả lời sai hoặc dùng thông tin cũ, cần đối chiếu văn bản chính thức","w":["Câu trả lời của AI đã được cơ quan nhà nước kiểm duyệt nên dùng được ngay","Hỏi vài chatbot khác nhau, nếu trả lời giống nhau thì chắc chắn đúng","AI chỉ sai với câu hỏi khó, câu hỏi đơn giản thì luôn đúng"],"h":"Ngay cả người thông minh nhất cũng có lúc nhầm.","e":"AI là công cụ hỗ trợ hữu ích nhưng có thể nhầm lẫn kể cả với câu hỏi đơn giản; nhiều chatbot có thể cùng sai vì học từ nguồn giống nhau. Câu trả lời của AI không được kiểm duyệt và không có giá trị pháp lý; hãy đối chiếu văn bản hoặc hỏi Trung tâm Phục vụ hành chính công phường."},{"q":"“Chính phủ số” hướng tới mục tiêu nào?","a":"Hoạt động dựa trên dữ liệu và công nghệ số, phục vụ người dân tốt hơn, lấy người dân làm trung tâm","w":["Chuyển toàn bộ hồ sơ giấy thành file scan lưu trên máy tính","Bắt buộc mọi người dân chỉ được làm thủ tục qua mạng","Thay thế cán bộ tiếp dân bằng máy móc, robot"],"h":"Trung tâm của Chính phủ số vẫn là con người.","e":"Chính phủ số dùng dữ liệu và công nghệ số để ra quyết định nhanh, minh bạch, cung cấp dịch vụ công thuận tiện. Scan hồ sơ chỉ là số hóa; người dân vẫn có thể làm thủ tục trực tiếp; công nghệ hỗ trợ chứ không thay thế con người."},{"q":"Từ ngày 01/7/2025, chính quyền địa phương ở nước ta được tổ chức như thế nào?","a":"Hai cấp: cấp tỉnh và cấp xã (xã, phường, đặc khu)","w":["Ba cấp: cấp tỉnh, cấp huyện và cấp xã","Hai cấp: cấp tỉnh và cấp huyện","Ba cấp: cấp tỉnh, cấp xã và khu phố, ấp"],"h":"Cấp huyện đã kết thúc hoạt động.","e":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, từ 01/7/2025 chính quyền địa phương được tổ chức ở cấp tỉnh và cấp xã; cả nước hiện có 34 tỉnh, thành phố và 3.321 xã, phường, đặc khu. Khu phố, ấp không phải là một cấp chính quyền."},{"q":"Theo Quyết định 2345/QĐ-NHNN (hiệu lực từ 01/7/2024), chuyển tiền trực tuyến trên 10 triệu đồng/lần phải xác thực bằng cách nào?","a":"Xác thực sinh trắc học (khuôn mặt hoặc vân tay)","w":["Nhập mã Smart OTP gửi về ứng dụng","Nhập lại mật khẩu đăng nhập thêm một lần","Xác nhận qua cuộc gọi từ tổng đài ngân hàng"],"h":"Gương mặt của bạn chính là chìa khóa.","e":"Quyết định 2345/QĐ-NHNN ngày 18/12/2023 quy định chuyển tiền trên 10 triệu đồng/lần hoặc tổng trên 20 triệu đồng/ngày phải xác thực sinh trắc học; các giao dịch nhỏ hơn mức đó vẫn dùng mã OTP. Biện pháp này giúp chống kẻ gian chiếm đoạt tài khoản."}]};
